("plus","Plus","ajouter créer nouveau"),("minus","Moins","retirer"),("x","Croix","fermer annuler supprimer"),("check","Coche","valider ok confirmer"),("search","Loupe","rechercher chercher"),("download","Télécharger","export"),("upload","Envoyer un fichier","importer upload"),
("send","Envoyer","message avion"),("save","Enregistrer","disquette sauver"),("trash-2","Corbeille","supprimer effacer"),("pencil","Crayon","modifier éditer"),("copy","Copier","dupliquer"),("share-2","Partager","réseau"),("external-link","Lien externe","ouvrir nouvel onglet"),("link","Lien","url chaîne"),
("log-in","Se connecter","connexion entrer"),("log-out","Se déconnecter","déconnexion sortir"),("user","Personne","compte profil utilisateur"),("users","Personnes","équipe groupe"),("settings","Réglages","paramètres engrenage"),("house","Accueil","maison home"),("menu","Menu","hamburger"),
("filter","Filtre","trier entonnoir"),("sliders-horizontal","Curseurs","réglages filtres"),("list","Liste","éléments"),("layout-grid","Grille","vignettes"),("calendar","Calendrier","date rendez-vous"),("clock","Horloge","heure temps"),("mail","Courriel","email message"),("phone","Téléphone","appel"),
("map-pin","Repère","lieu adresse carte"),("shopping-cart","Panier","achat commande"),("credit-card","Carte bancaire","paiement payer"),("heart","Cœur","aimer favori"),("star","Étoile","favori note"),("bookmark","Marque-page","enregistrer favori"),("bell","Cloche","notification alerte"),
("info","Info","information aide"),("circle-alert","Erreur","alerte attention"),("triangle-alert","Avertissement","alerte danger"),("circle-check","Rond coché","succès validé réussi"),("circle-x","Rond barré","erreur annuler échec"),("circle-question-mark","Aide","question"),("eye","Œil","voir afficher"),("eye-off","Œil barré","masquer cacher"),
("lock","Cadenas","sécurité verrouiller"),("lock-open","Cadenas ouvert","déverrouiller"),("refresh-cw","Actualiser","recharger"),("rotate-ccw","Annuler l’action","revenir défaire"),("play","Lecture","vidéo jouer"),("pause","Pause","arrêter"),("printer","Imprimer","impression"),
